  ('Career & Job Success Puja', 'career-job-success-baglamukhi-puja', 'briefcase', 70,
   'Career and Job Success Puja is offered by Nalkheda practitioners as a Baglamukhi-based karya siddhi service. It is meant for a specific, real concern: repeated interview failure, a promotion delay, workplace politics, job insecurity or career stagnation. The ritual includes Maa Baglamukhi pujan, mantra-japa and havan, and if the pandit recommends it, a supporting graha-shanti element that will be disclosed to you in advance. No puja can guarantee a job or a promotion — your skills, preparation, applications and professional decisions remain essential, and this is offered alongside them, not instead of them. Choose it if you are facing a job-search delay, interview nerves, a promotion or appraisal concern, workplace opposition, career stagnation, or job insecurity and transition.',
   'For job delay, interview pressure, promotion concerns, workplace opposition or career instability. A prayer for confidence, clarity, opportunity and the removal of obstacles.',
   '2-3 hours',
   'Selected by the pandit, and often timed before an interview, a joining date, an appraisal or another auspicious day.',
   'Live sankalp participation is possible, so the ritual can be timed around an interview or joining date.',
   '[{"icon":"🪔","title":"Career obstacle prayer","detail":"Traditionally sought for smoother professional progress."},{"icon":"🗣️","title":"Interview confidence","detail":"Supports mental steadiness and speech discipline."},{"icon":"🛡️","title":"Workplace protection","detail":"A prayer for protection from unfair rivalry or hostility."},{"icon":"🧘","title":"Decision clarity","detail":"A devotional process for calm career choices."},{"icon":"💼","title":"Opportunity sankalp","detail":"You can pray for suitable work opportunities."},{"icon":"🔥","title":"Motivation and discipline","detail":"The structure of the ritual reinforces focus alongside practical effort."}]'::jsonb,
   '[{"step":1,"title":"Career Sankalp","detail":"You state the job or career concern — an interview, a promotion or workplace pressure.","duration":""},{"step":2,"title":"Ganesh & Guru Pujan","detail":"Opening purification and blessings.","duration":""},{"step":3,"title":"Baglamukhi Pujan","detail":"Devi worship with the yellow offerings.","duration":""},{"step":4,"title":"Career / Karya Siddhi Mantra Jaap","detail":"The selected Baglamukhi mantra count is recited.","duration":""},{"step":5,"title":"Job & Career Havan","detail":"Ahutis are offered for obstacle removal and confidence.","duration":""},{"step":6,"title":"Purnahuti & Aarti","detail":"A closing prayer for the right opportunity and wise action.","duration":""}]'::jsonb,
   '[{"item":"Yellow cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Yellow flowers","qty":"as required"},{"item":"Turmeric / yellow mustard","qty":"as advised"},{"item":"Akshat / rice","qty":"1 bowl"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Incense, camphor, lamp","qty":"1 set"},{"item":"Fruits / sweets","qty":"as required"},{"item":"Puja thali basics","qty":"1 set"},{"item":"Resume / offer letter copy","qty":"optional, for the sankalp only"}]'::jsonb,
   '[{"q":"Can this puja guarantee a new job?","a":"No. It is spiritual support. Job outcomes depend on skills, applications, market conditions and interviews."},{"q":"Can I book it before an interview?","a":"Yes. The sankalp can be specifically for confidence, clear speech and a suitable outcome."},{"q":"Is it useful for promotion concerns?","a":"That is a common reason devotees book a career-oriented puja, but a promotion is never guaranteed."},{"q":"Can a student book it for campus placement?","a":"Yes. The sankalp can be adapted for a placement or first-job concern."},{"q":"Can it be online?","a":"Yes."},{"q":"Is a kundli review necessary?","a":"Not for a general devotional service. It may be added if a graha-specific remedy is being recommended."},{"q":"What else should I do?","a":"Continue with interview preparation, networking, applications and professional guidance alongside the puja."}]'::jsonb),

  ('Rog Nashak Puja', 'rog-nashak-baglamukhi-puja', 'sun', 80,
   'Rog Nashak services are offered by Nalkheda Baglamukhi practitioners, sometimes combining Pitambara/Baglamukhi worship with Maha Mrityunjaya or other health prayers. The puja is performed for spiritual strength, peace, courage and wellbeing during illness or recovery. It does not cure disease, replace a doctor, justify stopping any medicine, or guarantee recovery — please continue with the treatment your clinician has advised. The exact mantra and deity combination is disclosed by the assigned pandit before the booking is confirmed. Choose this service for a prayer during illness, a post-treatment or recovery phase, a family member''s health sankalp, mental strength during medical stress, a general wellbeing prayer, or health-related fear and uncertainty.',
   'A health and wellbeing prayer for devotees or family members going through illness, recovery, stress or a difficult health phase. Spiritual support only — it does not replace medical care.',
   '2-3 hours',
   'Selected by the pandit. An urgent health prayer need not wait for a distant festival — the priest can choose a suitable available muhurat.',
   'Can be performed in the patient''s name even if they are unable to attend, with the family joining by live sankalp.',
   '[{"icon":"🙏","title":"Wellbeing prayer","detail":"A devotional sankalp for health, strength and recovery."},{"icon":"🧘","title":"Mental peace","detail":"Supports calmness through a stressful health period."},{"icon":"👨‍👩‍👧","title":"Family spiritual support","detail":"Relatives can offer the ritual in the patient''s name."},{"icon":"🔥","title":"Courage","detail":"Mantra and prayer can provide emotional steadiness."},{"icon":"🛡️","title":"Protective devotion","detail":"Maa Baglamukhi is invoked for spiritual protection."},{"icon":"🕉️","title":"Optional Shiva prayer","detail":"Some practitioners combine Maha Mrityunjaya or Shiva-related prayers; your package states this clearly."}]'::jsonb,
   '[{"step":1,"title":"Health Sankalp","detail":"The patient''s name, gotra if known, and a simple wellbeing intention are recorded.","duration":""},{"step":2,"title":"Ganesh & Shuddhi Pujan","detail":"Opening purification and Ganesh worship.","duration":""},{"step":3,"title":"Baglamukhi / Health Deity Pujan","detail":"Maa Baglamukhi is worshipped; any additional Shiva or Mrityunjaya element is stated in advance.","duration":""},{"step":4,"title":"Mantra Jaap","detail":"The declared health-prayer mantra count is recited.","duration":""},{"step":5,"title":"Rog Nashak Havan","detail":"Havan is performed with the standard approved samagri.","duration":""},{"step":6,"title":"Purnahuti & Shanti Path","detail":"A closing peace prayer, followed by prasad.","duration":""}]'::jsonb,
   '[{"item":"Yellow/white cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Shiva image/lingam","qty":"only if the package includes the Mrityunjaya element"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Yellow/white flowers","qty":"as required"},{"item":"Bilva leaves","qty":"only if Shiva puja is included"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Akshat, turmeric, sandal","qty":"1 set"},{"item":"Incense, camphor, lamps","qty":"1 set"},{"item":"Fruits / satvik naivedya","qty":"as required"},{"item":"Patient photo/name sheet","qty":"optional, for the sankalp"}]'::jsonb,
   '[{"q":"Can this puja cure an illness?","a":"No. It is a spiritual prayer and must not replace medical diagnosis or treatment."},{"q":"Can it be performed for someone in hospital?","a":"Yes. The sankalp can be taken in that person''s name while they continue their medical care."},{"q":"Should medicines be stopped for the puja?","a":"No. Never stop prescribed treatment unless the treating clinician advises it."},{"q":"Is Maha Mrityunjaya included?","a":"Some practitioners include it and some do not. Your package states the actual mantra and deity combination."},{"q":"Can family members join online?","a":"Yes."},{"q":"How long does it take?","a":"Usually 2-3 hours for a standard puja-havan."},{"q":"What does the puja actually offer?","a":"Health and wellbeing prayer, spiritual support and mental strength during a difficult phase — never a cure or a guaranteed result."}]'::jsonb),

  ('Vivah Badha Nivaran Puja', 'vivah-badha-nivaran-baglamukhi-puja', 'rings', 90,
   'Vivah Badha Nivaran Puja is repeatedly listed by Nalkheda practitioners, though the exact format differs between them: some combine Baglamukhi worship with Mangal Shanti, Rahu-Ketu remedies or Swayamvar Parvati prayers. Your package will show clearly which of these are actually included, so nothing is assumed. The core intent is straightforward — repeated delay or obstacles in the path to marriage — and the ritual is offered as a prayer for a suitable, consensual and auspicious alliance. It never promises a particular person, forces a relationship, or guarantees marriage by a fixed date. Choose it if you face repeated marriage delay, proposal obstacles, family resistance, recurring misunderstandings, an astrology-linked marriage concern, or simply wish to pray for a suitable alliance.',
   'For people facing repeated marriage delay, proposal obstacles, misunderstandings or family resistance. A devotional prayer for suitable progress, clarity and harmony.',
   '2-4 hours; an extended anushthan may take multiple days',
   'Selected by the pandit or astrologer. A chart review may be useful if the service includes Mangal, Rahu-Ketu or other graha remedies.',
   'Live sankalp participation is possible, with the name, gotra and concern taken remotely before the ritual.',
   '[{"icon":"💍","title":"Marriage-obstacle prayer","detail":"Traditionally sought when marriage progress repeatedly stalls."},{"icon":"🧘","title":"Clarity and calm","detail":"Supports emotional steadiness through a stressful matchmaking phase."},{"icon":"🏠","title":"Family harmony sankalp","detail":"A prayer for the reduction of family-related tension can be included."},{"icon":"🌙","title":"Graha-shanti support","detail":"Where recommended, Mangal or Rahu-Ketu remedies may be added."},{"icon":"🤝","title":"Suitable-alliance prayer","detail":"Focused on an appropriate and mutually respectful marriage path."},{"icon":"🕉️","title":"Devi blessings","detail":"Maa Baglamukhi worship for protection and obstacle pacification."}]'::jsonb,
   '[{"step":1,"title":"Marriage Concern Sankalp","detail":"Name, gotra, age and the nature of the delay or obstacle are recorded.","duration":""},{"step":2,"title":"Ganesh & Kalash Pujan","detail":"The opening worship.","duration":""},{"step":3,"title":"Baglamukhi Pujan","detail":"Maa Baglamukhi is invoked with the yellow offerings.","duration":""},{"step":4,"title":"Optional Graha / Parvati Element","detail":"Only if included: Mangal Shanti, Rahu-Ketu or a Swayamvar Parvati-oriented prayer.","duration":""},{"step":5,"title":"Vivah Badha Havan","detail":"Havan ahutis are offered for obstacle removal and harmony.","duration":""},{"step":6,"title":"Purnahuti & Aarti","detail":"A closing prayer for a suitable, consensual and auspicious marriage path.","duration":""}]'::jsonb,
   '[{"item":"Yellow cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Yellow/red flowers","qty":"as required"},{"item":"Turmeric / kumkum / akshat","qty":"1 set"},{"item":"Moli / sacred thread","qty":"1"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Fruits / sweets","qty":"as required"},{"item":"Incense, camphor, lamps","qty":"1 set"},{"item":"Graha-specific samagri","qty":"only if included"},{"item":"Photo/biodata","qty":"optional, respectfully kept for the sankalp only"}]'::jsonb,
   '[{"q":"Does this puja guarantee marriage within a fixed time?","a":"No. It is a devotional remedy, and no fixed result or timeline is guaranteed."},{"q":"Can it make a specific person marry me?","a":"No. Coercive or non-consensual intentions are not accepted. The sankalp is for a suitable, mutual and auspicious relationship."},{"q":"Is Mangal Dosh Puja always included?","a":"No. It is included only if your package says so, and ideally after a kundli assessment."},{"q":"Can parents book it for their son or daughter?","a":"Yes, depending on the priest''s tradition — but the individual''s consent and dignity must be respected."},{"q":"Can it be online?","a":"Yes."},{"q":"What details are needed?","a":"Name, gotra if known, date of birth if astrology is being used, and a brief description of the concern."},{"q":"Is counselling or matchmaking still useful?","a":"Yes. Spiritual practice complements healthy communication, counselling and practical matchmaking efforts."}]'::jsonb),

  ('Santan Prapti Puja', 'santan-prapti-baglamukhi-puja', 'baby', 100,
   'Santan Prapti Anushthan is offered by several Nalkheda practitioners as a family and progeny-related prayer. The exact ritual may be Baglamukhi-centred, or may include Krishna/Santan Gopal, Shiva-Parvati or Navgraha prayers depending on the acharya, and the assigned pandit states exactly what will be performed. Because this is a medical and emotionally sensitive area, the service makes no promise of conception, offers no treatment for infertility and makes no claim about preventing miscarriage. It is devotional support for hope, family wellbeing and the couple''s shared sankalp. Choose it as a prayer for progeny, a couple''s family sankalp, emotional support during a fertility journey, a family wellbeing prayer, an astrology-guided santan concern, or devotional hope after a long wait.',
   'A devotional family prayer for couples seeking the blessing of children, hope and emotional strength. Spiritual support that does not replace fertility or obstetric care.',
   '2-4 hours; an anushthan format may run longer',
   'Selected by the pandit. If astrology is part of the package, birth details may be reviewed; no universal fixed time applies.',
   'The couple can join live, or the sankalp can be taken in both their names if they cannot attend.',
   '[{"icon":"👶","title":"Progeny prayer","detail":"A traditional devotional sankalp for the blessing of children."},{"icon":"🤝","title":"The couple''s shared worship","detail":"Creates a joint spiritual practice for both partners."},{"icon":"🕊️","title":"Hope and emotional support","detail":"A structured prayer to hold on to through a difficult journey."},{"icon":"🏠","title":"Family wellbeing","detail":"Includes a prayer for a healthy and harmonious family."},{"icon":"🌙","title":"Optional graha support","detail":"Some priests add Navgraha or other remedies where recommended."},{"icon":"🕉️","title":"Devi grace","detail":"Maa Baglamukhi is worshipped for protection and the removal of obstacles."}]'::jsonb,
   '[{"step":1,"title":"Couple Sankalp","detail":"Both partners'' names, gotra and the family prayer are recorded.","duration":""},{"step":2,"title":"Ganesh & Kalash Pujan","detail":"Opening purification and worship.","duration":""},{"step":3,"title":"Baglamukhi / Santan-related Pujan","detail":"The specific deity combination named in your package is worshipped.","duration":""},{"step":4,"title":"Mantra Jaap","detail":"The declared mantra count is recited in the couple''s sankalp.","duration":""},{"step":5,"title":"Santan Prapti Havan","detail":"Havan ahutis are offered as prescribed.","duration":""},{"step":6,"title":"Purnahuti & Family Blessing Prayer","detail":"A closing prayer for wellbeing, patience and family blessings.","duration":""}]'::jsonb,
   '[{"item":"Yellow cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Santan Gopal/Krishna image","qty":"only if included"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Yellow/white flowers","qty":"as required"},{"item":"Tulsi","qty":"only if the Krishna element is included"},{"item":"Akshat, turmeric, sandal","qty":"1 set"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Fruits / sweets","qty":"as required"},{"item":"Incense, camphor, lamps","qty":"1 set"},{"item":"Couple photo","qty":"optional, for the sankalp"}]'::jsonb,
   '[{"q":"Does this puja guarantee pregnancy?","a":"No. It is a spiritual practice and cannot guarantee conception."},{"q":"Should we continue fertility treatment?","a":"Yes. Continue with the medical evaluation and treatment recommended by qualified clinicians."},{"q":"Do both partners need to be present?","a":"Not always. Both names can be included in the sankalp, and live participation can be arranged where available."},{"q":"Is Santan Gopal Puja automatically included?","a":"No. Some practitioners combine it, others perform a Baglamukhi-specific anushthan. Your package discloses this."},{"q":"Can it be online?","a":"Yes."},{"q":"Do we need a kundli?","a":"Only if the pandit is adding astrology-based graha remedies."},{"q":"What does the service actually offer?","a":"Prayer, hope, spiritual support and a family blessing — never a medical claim or a promised outcome."}]'::jsonb),

  ('Graha Shanti Puja', 'graha-shanti-baglamukhi-puja', 'moon', 110,
   'Grah Dosh Nivaran and Navgraha Shanti are commonly offered alongside Maa Baglamukhi worship at Nalkheda. If you are paying for a specific dosha remedy, the ritual should never be generic: the assigned pandit identifies whether the focus is Shani, Rahu-Ketu, Mangal, the full Navgraha or another graha. A typical package includes Ganesh puja, Navgraha avahan, graha mantra-japa, Maa Baglamukhi pujan and havan. A kundli review is encouraged before any personalised graha claim is made — a difficult phase in life is not by itself proof that you have a dosha, and you will not be told otherwise here. Choose this service for a kundli-identified graha dosha, a Rahu-Ketu, Shani or Mangal-related concern, multiple planetary concerns, or a general Navgraha shanti.',
   'For devotees who have been advised that one or more planetary influences may need shanti. Combines Baglamukhi protection with the appropriate graha or Navgraha worship.',
   '2.5-4 hours',
   'Ideally after a kundli review when the service is dosha-specific. The date is selected according to the relevant graha and the local Panchang.',
   'Live sankalp participation is possible; birth details can be shared in advance for a dosha-specific booking.',
   '[{"icon":"🌙","title":"Graha shanti prayer","detail":"Traditional worship for planetary pacification."},{"icon":"🛡️","title":"Baglamukhi protection","detail":"Combines graha remedies with a Devi protection-oriented prayer."},{"icon":"📿","title":"Personalised sankalp","detail":"Can be tailored to the specific graha identified in your chart."},{"icon":"🧘","title":"Mental steadiness","detail":"A structured spiritual response to an astrological concern."},{"icon":"🪔","title":"Obstacle pacification","detail":"Often chosen when repeated delays are associated with planetary periods."},{"icon":"🕉️","title":"Navgraha reverence","detail":"Honours the planetary deities according to Vedic-astrological tradition."}]'::jsonb,
   '[{"step":1,"title":"Kundli / Concern Review","detail":"The relevant graha is identified, or a general Navgraha service is agreed.","duration":""},{"step":2,"title":"Ganesh & Kalash Pujan","detail":"The opening worship.","duration":""},{"step":3,"title":"Navgraha / Specific Graha Avahan","detail":"The relevant grahas are invoked and worshipped.","duration":""},{"step":4,"title":"Baglamukhi Pujan & Mantra","detail":"Maa Baglamukhi is worshipped for protection and obstacle pacification.","duration":""},{"step":5,"title":"Graha Shanti Havan","detail":"Havan is performed with graha-appropriate and Baglamukhi samagri.","duration":""},{"step":6,"title":"Purnahuti & Daan Guidance","detail":"A closing prayer; any traditional daan is suggested by the pandit rather than fixed in advance.","duration":""}]'::jsonb,
   '[{"item":"Navgraha set / symbols","qty":"1 set"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Navdhanya / nine grains","qty":"1 set if Navgraha is included"},{"item":"Flowers","qty":"appropriate / available colours"},{"item":"Akshat, roli, sandal, moli","qty":"1 set"},{"item":"Ghee","qty":"500 ml approx."},{"item":"Havan samagri","qty":"1 pack"},{"item":"Graha-specific sesame/grains","qty":"as advised"},{"item":"Incense, camphor, lamps","qty":"1 set"},{"item":"Fruits / sweets","qty":"as required"},{"item":"Daan items","qty":"only as advised by the pandit"}]'::jsonb,
   '[{"q":"Do I need a kundli?","a":"For a specific dosha remedy, a kundli review is strongly recommended. A general Navgraha prayer can be performed without a personalised diagnosis."},{"q":"Is this the same as Navgraha Shanti Puja?","a":"It may include Navgraha Shanti, but the Baglamukhi version also adds Maa Baglamukhi worship. Your package states the exact scope."},{"q":"Can it include Rahu-Ketu or Shani remedies?","a":"Yes, if those are the identified concerns and the assigned pandit includes them."},{"q":"Can it be online?","a":"Yes."},{"q":"Is one muhurat suitable for every graha?","a":"No. Timing may vary by the graha, the chart and the local Panchang."},{"q":"Does a bad phase prove that I have graha dosha?","a":"No. Life difficulties alone are not proof of an astrological dosha."},{"q":"Are results guaranteed?","a":"No. This is a traditional spiritual and astrological practice."}]'::jsonb),

  ('Tantra Badha / Negative Energy Protection Puja', 'tantra-badha-negative-energy-protection-baglamukhi-puja', 'diya', 120,
   'This category is offered carefully, and it is worth saying why. Fear, anxiety, illness, financial loss or a relationship problem is not proof of black magic or tantra badha, and you will not be told that it is. This is an optional spiritual protection ritual for devotees who find meaning in the tradition, and practical or professional help for real-world problems is encouraged alongside it. The ritual includes Baglamukhi pujan, protective mantra-japa, havan and shanti prayers. Any advanced tantric method stays under a qualified acharya and never involves harm, coercion or dangerous substances. Choose this service for perceived negativity, a nazar-related spiritual concern, fear of harmful influence, an uneasy home or work environment, repeated unexplained spiritual worry, or a general protection sankalp.',
   'For devotees worried about perceived negative spiritual influence, fear, nazar-like disturbance or repeated unexplained uneasiness. Focused on protection, peace and grounding — without claiming that black magic has been proven.',
   '2-4 hours; an extended anushthan may take longer',
   'Consultation-based. The acharya chooses a suitable tithi and method — advanced tantric details should never be self-prescribed.',
   'Available after a consultation and a clear, non-harmful sankalp is agreed with the pandit.',
   '[{"icon":"🛡️","title":"Protection prayer","detail":"Maa Baglamukhi is invoked for spiritual protection and steadiness."},{"icon":"🪔","title":"Peace and grounding","detail":"A structured, calming devotional process."},{"icon":"🕊️","title":"Fear reduction","detail":"Supports devotees who feel spiritually unsettled, without validating unproven causes."},{"icon":"🏠","title":"Home and environment shanti","detail":"Can be offered with a prayer for a calmer environment."},{"icon":"🧘","title":"Obstacle pacification","detail":"Focused on reducing recurring disturbance and perceived negativity."},{"icon":"🙏","title":"Ethical spiritual guidance","detail":"A qualified pandit can steer you away from harmful or exploitative practices."}]'::jsonb,
   '[{"step":1,"title":"Private Concern Discussion","detail":"The pandit listens, without declaring that black magic is definitely present.","duration":""},{"step":2,"title":"Protection Sankalp & Shuddhi","detail":"A non-harmful protection and peace intention is taken.","duration":""},{"step":3,"title":"Baglamukhi Avahan","detail":"Maa Baglamukhi is worshipped with the standard yellow offerings.","duration":""},{"step":4,"title":"Protective Mantra Jaap","detail":"The acharya recites the appropriate traditional mantra.","duration":""},{"step":5,"title":"Protection Havan","detail":"Havan is performed with safe, prescribed samagri.","duration":""},{"step":6,"title":"Purnahuti & Shanti Guidance","detail":"A final prayer for peace and confidence, with practical next steps where they are needed.","duration":""}]'::jsonb,
   '[{"item":"Yellow cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Turmeric / yellow mustard","qty":"as advised"},{"item":"Yellow flowers","qty":"as required"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Samidha / wood","qty":"as required"},{"item":"Akshat, sandal, roli, moli","qty":"1 set"},{"item":"Incense, camphor, lamp","qty":"1 set"},{"item":"Salt/lemon/chilli or other folk items","qty":"only if the qualified pandit specifically uses them; not a default"},{"item":"Naivedya","qty":"as required"}]'::jsonb,
   '[{"q":"How do I know if I have tantra badha or black magic?","a":"We do not diagnose this. Many ordinary medical, psychological, financial or relationship problems can feel unexplained — please seek appropriate professional help where it is relevant."},{"q":"What is this puja for, then?","a":"It is a spiritual protection and peace ritual for devotees who wish to follow the Baglamukhi tradition."},{"q":"Can it harm another person?","a":"No. Only protection-oriented, non-harmful sankalps are accepted."},{"q":"Can it be performed online?","a":"Yes, once the pandit understands the concern and the sankalp is agreed."},{"q":"Are special ingredients always used?","a":"No. Methods differ by lineage. Advanced or unusual samagri should never be assumed or used on your own."},{"q":"Should I stop medical or mental-health treatment?","a":"No."},{"q":"Can the pandit guarantee that negativity will disappear?","a":"No. No spiritual outcome is guaranteed."}]'::jsonb),

  ('Sarva Badha Nivaran Puja', 'sarva-badha-nivaran-baglamukhi-puja', 'om', 130,
   'Sarva Badha Nivaran is the right starting point when the difficulty is broad rather than specific. Nalkheda practitioners use this name when a devotee reports recurring blocks across career, family, business or mental peace but has no single clear diagnosis or purpose. Rather than pushing you into Court Case, Graha Shanti or Tantra Badha, this service takes a general protection and obstacle-removal sankalp. The ritual includes sankalp, Ganesh puja, Maa Baglamukhi pujan, mantra-japa, havan and purnahuti. If the consultation reveals a more specific need, the pandit can recommend a suitable related service — with your approval before anything changes. Choose it for multiple recurring obstacles, an unclear source of difficulty, a general protection prayer, mixed family and work stress, repeated delays, or when you are simply unsure which Baglamukhi service fits.',
   'For devotees facing repeated obstacles in more than one area of life, and unsure which specialised service to choose. A broad Baglamukhi prayer for protection, clarity, peace and the removal of obstacles.',
   '2-4 hours',
   'A general auspicious Devi muhurat selected by the pandit — suitable when the concern is broad rather than one specific dosha.',
   'Live sankalp participation is possible, with the general concern discussed before the ritual is fixed.',
   '[{"icon":"🕉️","title":"Broad obstacle prayer","detail":"Suitable when problems span more than one area of life."},{"icon":"🛡️","title":"Protection","detail":"A traditional Baglamukhi protection sankalp."},{"icon":"🧭","title":"Clarity","detail":"Allows a general spiritual reset without inventing a specific dosha."},{"icon":"🧘","title":"Peace and steadiness","detail":"Supports a calmer response to repeated setbacks."},{"icon":"🪔","title":"Flexible ritual","detail":"The pandit can adapt the mantra and samagri after understanding your concern."},{"icon":"🤝","title":"Gateway to specific guidance","detail":"If a clear issue emerges, you can be referred to a more specialised service."}]'::jsonb,
   '[{"step":1,"title":"General Concern & Sankalp","detail":"You briefly explain the main areas of repeated difficulty.","duration":""},{"step":2,"title":"Shuddhi, Ganesh & Kalash Pujan","detail":"Opening purification and auspicious worship.","duration":""},{"step":3,"title":"Maa Baglamukhi Pujan","detail":"The Devi is invoked with the yellow offerings.","duration":""},{"step":4,"title":"Sarva Badha Mantra Jaap","detail":"Baglamukhi mantra-japa for broad protection and obstacle pacification.","duration":""},{"step":5,"title":"Sarva Badha Nivaran Havan","detail":"A standard havan with safe, prescribed samagri.","duration":""},{"step":6,"title":"Purnahuti, Aarti & Guidance","detail":"A closing prayer; the pandit suggests a specific follow-up only if one is genuinely needed.","duration":""}]'::jsonb,
   '[{"item":"Yellow cloth","qty":"1"},{"item":"Baglamukhi image/yantra","qty":"1"},{"item":"Kalash & coconut","qty":"1 set"},{"item":"Yellow flowers","qty":"as required"},{"item":"Turmeric / yellow mustard","qty":"as advised"},{"item":"Akshat / rice","qty":"1 bowl"},{"item":"Ghee","qty":"250-500 ml"},{"item":"Havan samagri","qty":"1 pack"},{"item":"Mango wood / samidha","qty":"as required"},{"item":"Roli, moli, sandal, supari","qty":"1 set"},{"item":"Incense, camphor, lamp","qty":"1 set"},{"item":"Fruits / sweets","qty":"as required"}]'::jsonb,
   '[{"q":"When should I choose Sarva Badha Nivaran instead of another service?","a":"Choose it when you face several recurring obstacles and have no one clear issue such as a court case or a specific graha dosha."},{"q":"Is this a general Baglamukhi Havan?","a":"It is closely related, but the sankalp is specifically framed around broad obstacle removal and protection."},{"q":"Do I need a kundli?","a":"No, not for a general service. A kundli is only needed if a graha-specific remedy is later considered."},{"q":"Can it be online?","a":"Yes."},{"q":"Does it include Shatru Stambhan?","a":"Not automatically. It is a broad protection service; any specialised element is disclosed if it is added."},{"q":"Can the pandit change the service after the consultation?","a":"The pandit may recommend a more suitable option, but you approve any change in scope or price before it happens."},{"q":"Are results guaranteed?","a":"No. It is a devotional practice, and practical action should continue alongside it."}]'::jsonb)
)
INSERT INTO public.services
  (category_id, name, slug, icon_name, display_order,
   description, short_description, estimated_duration,
   recommended_muhurat, online_note,
   benefits, process, samagri_list, faqs,
   is_online_available, is_popular, is_active)
SELECT (SELECT id FROM cat),
       i.name, i.slug, i.icon_name, i.display_order,
       i.description, i.short_description, i.estimated_duration,
       i.recommended_muhurat, i.online_note,
       i.benefits, i.process, i.samagri_list, i.faqs,
       TRUE,   -- every one of the thirteen is offered with remote sankalp
       FALSE,  -- "popular" is an admin's editorial call, not a seed's
       FALSE   -- draft until an admin adds the image and activates it
  FROM incoming i
ON CONFLICT (slug) DO NOTHING;

-- ----------------------------------------------------------------------------
-- Self-check
-- ----------------------------------------------------------------------------
DO $verify$
DECLARE
  found INT;
BEGIN
  SELECT COUNT(*) INTO found
    FROM public.services s
    JOIN public.service_categories sc ON sc.id = s.category_id
   WHERE s.slug IN ('court-case-vijay-baglamukhi-puja',
                    'shatru-stambhan-baglamukhi-puja',
                    'shatru-nash-protection-baglamukhi-puja',
                    'rajneeti-vijay-baglamukhi-puja',
                    'business-growth-baglamukhi-puja',
                    'lakshmi-dhan-prapti-baglamukhi-puja',
                    'career-job-success-baglamukhi-puja',
                    'rog-nashak-baglamukhi-puja',
                    'vivah-badha-nivaran-baglamukhi-puja',
                    'santan-prapti-baglamukhi-puja',
                    'graha-shanti-baglamukhi-puja',
                    'tantra-badha-negative-energy-protection-baglamukhi-puja',
                    'sarva-badha-nivaran-baglamukhi-puja');

  IF found <> 13 THEN
    RAISE EXCEPTION 'Migration 0013 incomplete — expected 13 Baglamukhi sub-services, found %', found;
  END IF;
END
$verify$;
